fn solve(a: i8, b: i8, c: i8) -> i8 {
    // Find the maximum of the three integers
    let max_value = a.max(b).max(c);
    
    // Calculate the differences from the maximum
    let diff_a = max_value - a;
    let diff_b = max_value - b;
    let diff_c = max_value - c;

    // Calculate the total number of operations needed
    // Each operation can either increase one integer by 2 or two integers by 1
    // We can use the two-increment operation as much as possible
    let total_diff = diff_a + diff_b + diff_c;

    // The number of operations needed is the total difference divided by 2,
    // plus any remaining single increments needed
    let operations = total_diff / 2 + total_diff % 2;

    operations
}